#include <iostream>
#include <memory>
#include <vector>
#include <string>

// ── Node in a simple scene graph ──────────────────────────────────────────
struct Node {
    std::string name;
    std::weak_ptr<Node> parent;            // non-owning: breaks potential cycle
    std::vector<std::shared_ptr<Node>> children;

    explicit Node(std::string n) : name(std::move(n)) {}

    void addChild(std::shared_ptr<Node> child) {
        child->parent = shared_from_this();
        children.push_back(std::move(child));
    }

    void print(int depth = 0) const {
        std::cout << std::string(depth * 2, ' ') << "▸ " << name;
        if (auto p = parent.lock())
            std::cout << "  (parent: " << p->name << ")";
        std::cout << "\n";
        for (const auto& c : children) c->print(depth + 1);
    }
};

// ── Factory using unique_ptr for exclusive ownership ───────────────────────
std::unique_ptr<int[]> makeBuffer(std::size_t n) {
    return std::make_unique<int[]>(n);      // unique ownership; no delete needed
}

// ── Custom deleter for non-memory resources ────────────────────────────────
void demonstrateCustomDeleter() {
    auto fileClose = [](FILE* f) {
        if (f) { std::cout << "[deleter] fclose called\n"; fclose(f); }
    };
    // FILE is automatically closed when unique_ptr goes out of scope
    std::unique_ptr<FILE, decltype(fileClose)> logFile(fopen("/dev/null", "w"), fileClose);
}

int main() {
    std::cout << "=== Day 05: Smart Pointers & Ownership ===\n\n";

    // ── 1. unique_ptr: exclusive ownership ────────────────────────────────
    {
        auto widget = std::make_unique<int>(42);
        std::cout << "unique_ptr value: " << *widget << "\n";
        auto moved = std::move(widget);     // widget is now nullptr
        std::cout << "after move, widget is null: " << (widget == nullptr) << "\n";
    }  // moved goes out of scope → int(42) deleted

    // ── 2. shared_ptr: reference counting ─────────────────────────────────
    {
        auto shared = std::make_shared<std::string>("shared resource");
        std::cout << "\nuse_count after make_shared: " << shared.use_count() << "\n";
        {
            auto copy = shared;   // count → 2
            std::cout << "use_count with copy alive: " << shared.use_count() << "\n";
        }  // copy destroyed → count back to 1
        std::cout << "use_count after copy scope: " << shared.use_count() << "\n";
    }

    // ── 3. weak_ptr: non-owning, cycle-safe ───────────────────────────────
    {
        std::weak_ptr<int> weak;
        {
            auto strong = std::make_shared<int>(99);
            weak = strong;
            std::cout << "\nweak.lock() while alive: " << *weak.lock() << "\n";
        }  // strong destroyed
        std::cout << "weak.expired() after strong gone: " << weak.expired() << "\n";
    }

    // ── 4. Scene graph with shared + weak ─────────────────────────────────
    std::cout << "\nScene graph:\n";
    // Root must be shared_ptr for enable_shared_from_this to work
    // (simplified: just use shared_ptr nodes with weak back-refs)
    auto root  = std::make_shared<Node>("root");
    auto child = std::make_shared<Node>("child");
    auto leaf  = std::make_shared<Node>("leaf");

    // Wire up ownership manually (simplified, without enable_shared_from_this)
    child->parent = root;
    leaf->parent  = child;
    child->children.push_back(leaf);
    root->children.push_back(child);
    root->print();

    // ── 5. Custom deleter ─────────────────────────────────────────────────
    std::cout << "\nCustom deleter demo:\n";
    demonstrateCustomDeleter();

    return 0;
}
